import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 19
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))

    start = 0
    while start < len(records) and (
        not records[start]
        or (len(records[start]) == 1 and not records[start][0].strip())
    ):
        start += 1
    if start == len(records):
        return {"columns": [], "rows": []}

    # Look for the table header after an optional short preamble.
    if len(records[start]) <= 2:
        for index in range(start + 1, len(records)):
            if len(records[index]) == expected_width:
                start = index
                break

    columns = records[start][:]
    rows = records[start + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Preserve the original header, including empty labels, and keep all
    # fields from overwide records by adding columns rather than truncating.
    used = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"extra_column_{position}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
